-- Own joined classroom only. No credentials or production identities.
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',false);
select student_assert('History contains only my joined sessions',jsonb_array_length(get_my_rizsim_student_workspace()->'attempts')=2);
select student_assert('Server clock is returned',(get_my_rizsim_student_workspace()->>'server_time')::timestamptz between now()-interval '1 second' and now()+interval '1 second');
select student_assert('Open practice marked eligible',(select bool_and((x->>'can_practice')::boolean) from jsonb_array_elements(get_my_rizsim_student_workspace()->'attempts') x));
select student_assert('No share token leaked',(select bool_and(not(x?'share_token')) from jsonb_array_elements(get_my_rizsim_student_workspace()->'attempts') x));
select student_assert('No instructor licence IDs leaked',(select bool_and(not(x?'license_id')) from jsonb_array_elements(get_my_rizsim_student_workspace()->'attempts') x));
select student_assert('Own class code available for secure existing resolver',(select bool_and(length(x->>'class_code')=8) from jsonb_array_elements(get_my_rizsim_student_workspace()->'attempts') x));
select student_assert('Resume keeps the same attempt',(select (resume_my_rizsim_student_practice(id)->>'attempt_id')::uuid=id from simulation_attempts limit 1));
select student_assert('Resume cannot create duplicate attempts',(select count(*)=2 from simulation_attempts));
update simulation_attempts set classroom_access_type='live' where classroom_session_id='50000000-0000-4000-8000-000000000001';
update classroom_sessions set access_mode='both' where id='50000000-0000-4000-8000-000000000001';
select resume_my_rizsim_student_practice(id) from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001';
select student_assert('Explicit live to practice transition keeps progress',(select classroom_access_type='practice' and progress_percent=25 and status='in_progress' from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001'));
update simulation_attempts set status='submitted',submitted_at=now() where classroom_session_id='50000000-0000-4000-8000-000000000001';
select student_assert('Submitted practice is classified separately',(select x->>'practice_state'='submitted' and (x->>'can_practice')::boolean=false from jsonb_array_elements(get_my_rizsim_student_workspace()->'attempts')x where x->>'classroom_session_id'='50000000-0000-4000-8000-000000000001'));
select student_reject('Submitted work cannot be reopened',format('select resume_my_rizsim_student_practice(%L)',(select id from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001')));
update simulation_attempts set status='in_progress' where classroom_session_id='50000000-0000-4000-8000-000000000001';
select student_reject('Submitted timestamp alone prevents reopening',format('select resume_my_rizsim_student_practice(%L)',(select id from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001')));
update simulation_attempts set submitted_at=null;
update classroom_sessions set practice_starts_at=now()+interval '1 hour' where id='50000000-0000-4000-8000-000000000001';
select student_assert('Future practice is scheduled not complete',(select x->>'practice_state'='scheduled' from jsonb_array_elements(get_my_rizsim_student_workspace()->'attempts')x where x->>'classroom_session_id'='50000000-0000-4000-8000-000000000001'));
select student_reject('Future practice cannot start early',format('select resume_my_rizsim_student_practice(%L)',(select id from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001')));
update classroom_sessions set practice_starts_at=now()-interval '1 hour',practice_ends_at=now()-interval '1 second' where id='50000000-0000-4000-8000-000000000001';
select student_assert('Past practice is expired not complete',(select x->>'practice_state'='expired' from jsonb_array_elements(get_my_rizsim_student_workspace()->'attempts')x where x->>'classroom_session_id'='50000000-0000-4000-8000-000000000001'));
select student_reject('Expired practice cannot start',format('select resume_my_rizsim_student_practice(%L)',(select id from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001')));
update classroom_sessions set practice_ends_at=now()+interval '3 hours',active=false where id='50000000-0000-4000-8000-000000000001';
select student_reject('Faculty-closed session cannot resume',format('select resume_my_rizsim_student_practice(%L)',(select id from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001')));
update classroom_sessions set active=true where id='50000000-0000-4000-8000-000000000001';
update simulation_licenses set revoked_at=now() where id='40000000-0000-4000-8000-000000000001';
select student_reject('Revoked simulation licence cannot resume',format('select resume_my_rizsim_student_practice(%L)',(select id from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001')));
update simulation_licenses set revoked_at=null,expires_at=now()+interval '1 hour' where id='40000000-0000-4000-8000-000000000001';
select student_assert('Countdown cannot outlive licence',(select (x->>'practice_access_ends_at')::timestamptz<=(select expires_at from simulation_licenses where id='40000000-0000-4000-8000-000000000001') from jsonb_array_elements(get_my_rizsim_student_workspace()->'attempts')x where x->>'classroom_session_id'='50000000-0000-4000-8000-000000000001'));
update rizsim_courses set active=false where id='20000000-0000-4000-8000-000000000001';
select student_reject('Ended course cannot grant practice',format('select resume_my_rizsim_student_practice(%L)',(select id from simulation_attempts where classroom_session_id='50000000-0000-4000-8000-000000000001')));
update rizsim_courses set active=true where id='20000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',false);
select student_assert('Other learner gets no foreign history',jsonb_array_length(get_my_rizsim_student_workspace()->'attempts')=0);
select student_reject('Foreign attempt ID rejected',format('select resume_my_rizsim_student_practice(%L)',(select id from simulation_attempts limit 1)));
update profiles set account_status='suspended' where id='10000000-0000-4000-8000-000000000003';
select student_reject('Suspended profile cannot read student workspace','select get_my_rizsim_student_workspace()');
select set_config('request.jwt.claim.sub','',false);
select student_reject('Anonymous request denied','select get_my_rizsim_student_workspace()');
select student_assert('Anonymous execution privilege denied',not has_function_privilege('anon','get_my_rizsim_student_workspace()','execute') and not has_function_privilege('anon','resume_my_rizsim_student_practice(uuid)','execute'));
select student_assert('Authenticated read granted',has_function_privilege('authenticated','get_my_rizsim_student_workspace()','execute'));
select student_assert('No new sessions created',(select count(*)=2 from classroom_sessions));
select student_assert('No licences created',(select count(*)=2 from simulation_licenses));
select student_assert('Practice never changed progress or submissions',(select bool_and(progress_percent=25 and status='in_progress' and submitted_at is null) from simulation_attempts));
